  "paywall.event": { fr: "Plan jusqu'à ton événement", en: "Plan through your event", de: "Plan bis zu deinem Event", es: "Plan hasta tu evento", ja: "大会までのプラン", nl: "Plan tot je evenement", it: "Piano fino al tuo evento", pt: "Plano até ao teu evento", "pt-BR": "Plano até o seu evento", sv: "Plan fram till ditt lopp", da: "Plan frem til dit stævne", nb: "Plan frem til stevnet ditt", fi: "Suunnitelma tapahtumaasi asti" },
