Object.assign(ROWS, EXTRA_ROWS);

function nest(lang) {
  const out = {};
  for (const [path, row] of Object.entries(ROWS)) {
    const parts = path.split(".");
    let cur = out;
    for (let i = 0; i < parts.length - 1; i += 1) {
      if (!cur[parts[i]] || typeof cur[parts[i]] !== "object") cur[parts[i]] = {};
      cur = cur[parts[i]];
    }
    cur[parts[parts.length - 1]] = row[lang] || row.en || row.fr;
  }
  return out;
}

export const APP_COPY = Object.fromEntries(LANGS.map((lng) => [lng, nest(lng)]));
